import numpy as np


def min_max_dist_dim2_16() -> np.ndarray:
    """Construct 16 points from the specified radius-two hexagonal lattice subset."""

    radius = 2
    excluded = {(0, -2), (1, -2), (2, -2)}
    points = [
        (q + 0.5 * r, (np.sqrt(3.0) / 2.0) * r)
        for q in range(-radius, radius + 1)
        for r in range(-radius, radius + 1)
        if max(abs(q), abs(r), abs(q + r)) <= radius
        and (q, r) not in excluded
    ]
    return np.asarray(points, dtype=float)
